# -*- coding: utf-8 -*-
# Bank soal tambahan per stasiun per level. Tipe:
#   mc  : pilihan ganda  (t, benar, [salah], penjelasan, hlm)   SMP 2 salah, dewasa 3 salah
#   mu  : pilih 2 dari 5 (t, [2 benar], [3 salah], penjelasan, hlm)
#   or  : urutkan        (t, [item sesuai urutan benar], penjelasan, hlm)  SMP 3 item, dewasa 4 item
#   mt  : jodohkan       (t, [(kiri, kanan) x3], penjelasan, hlm)
def mc(t,b,w,e,h):return dict(ty='mc',t=t,b=b,w=w,e=e,h=h)
def mu(t,b,w,e,h):return dict(ty='mu',t=t,b=b,w=w,e=e,h=h)
def orr(t,it,e,h):return dict(ty='or',t=t,it=it,e=e,h=h)
def mt(t,pairs,e,h):return dict(ty='mt',t=t,pairs=pairs,e=e,h=h)
